class Session {
  #token = "";
  #expiresAt = 0;

  constructor(token, expiresAt) {
    this.#token = token;
    this.#expiresAt = expiresAt;
  }

  get isValid() {
    return Date.now() < this.#expiresAt;
  }

  get preview() {
    return this.#token.slice(0, 4) + "…";
  }

  rotate(newToken) {
    if (!this.isValid) throw new Error("expired");
    this.#token = newToken;
  }
}

const s = new Session("secret-jwt", Date.now() + 60_000);
console.log(s.preview);     // secr…
// console.log(s.#token);   // SyntaxError outside class

// TypeScript source
class CacheEntry {
  private key = "";   // compile-time only
  #hash = "";         // runtime private if emit targets ES2022+

  constructor(key: string) {
    this.key = key;
    this.#hash = hash(key);
  }
}

// Emitted JS (conceptual): key is public on the object
// entry.key is readable in DevTools — entry.#hash throws

const secretKey = Symbol("secret");

class Config {
  constructor(value) {
    this[secretKey] = value;
  }
  reveal(sym) {
    if (sym === secretKey) return this[secretKey];
    throw new Error("denied");
  }
}

const c = new Config("api-key");
console.log(c.reveal(secretKey)); // api-key
console.log(Object.keys(c));      // [] — not enumerated
// Anyone exporting secretKey can read the value

const internals = new WeakMap();

class LegacySession {
  constructor(token) {
    internals.set(this, { token });
  }
  preview() {
    return internals.get(this).token.slice(0, 4);
  }
}

const s = new LegacySession("hidden");
console.log(s.preview()); // hidd
// No property on s — DevTools shows empty own keys

